The following diffusion processes are commonly used to model financial asset price processes:
\begin{equation}
d{\bf X}_t = \boldsymbol{\mu}_tdt + \boldsymbol{\Theta}_td{\bf W}_t, \hspace{1cm} t\in [0,1], \end{equation}
where $(\boldsymbol{\mu}_t) = (\mu_t^{(1)},\cdots,\mu_t^{(p)})^\mathrm{T}$ is a $p$-dimensional drift process, $(\boldsymbol{\Theta}_t)$ is a $p\times p$ matrix, the so-called covolatility process at time $t$, and $({\bf W}_t)$ is a $p$-dimensional standard Brownian motion.

The integrated covariance (ICV) matrix given by
\begin{equation}
\textrm{ICV} :=\int_0^1 \boldsymbol{\Theta}_t\boldsymbol{\Theta}_t^\mathrm{T} dt \end{equation}
is of fundamental importance in risk management and portfolio allocation for high-frequency financial data.

Suppose that $({\bf X}_t)$ is a $p$-dimensional process satisfying (\ref{eq: Model}) and $\boldsymbol{\Theta}_t$ is c\`{a}dl\`{a}g. Then $({\bf X}_t)$ belongs to class $\mathcal{C}$ if, almost surely, there exist $\gamma_t\in D([0,1]; \mathbb{R})$ and $\boldsymbol{\Lambda}$ a $p\times p$ matrix satisfying $\begin{rm}tr\end{rm}(\boldsymbol{\Lambda}\boldsymbol{\Lambda}^\mathrm{T}) = p$ such that
\begin{equation}
\bm\Theta_t = \gamma_t \bm \Lambda, \end{equation}
where $D([0,1]; \mathbb{R})$ is the space of c\`{a}dl\`{a}g functions from $[0,1]$ to $\mathbb{R}$.

To investigate the effect of multiple transactions, we start by studying the non-overlapping averaged TVA (ATVA)  matrix, ${\mathcal A}_N$, which is defined as

\begin{equation}
{\mathcal A}_N :=
\dfrac{\sum_{i=1}^N |\Delta \overline{{\bf X}}_{2i}|^2}{N} \cdot
\sum_{i=1}^N \dfrac{\Delta\overline{{\bf X}}_{2i} \Delta\overline{{\bf X}}_{2i}^T}{|\Delta\overline{{\bf X}}_{2i}|^2}
= \dfrac{\sum_{i=1}^N |\Delta \overline{{\bf X}}_{2i}|^2}{p}
\cdot \widetilde{\boldsymbol{\Sigma}},
\end{equation}
where $N=\lfloor n/2 \rfloor$, $\widetilde{\boldsymbol{\Sigma}}=\dfrac pN \sum_{i=1}^N \dfrac{\Delta\overline{{\bf X}}_{2i} \Delta\overline{{\bf X}}_{2i}^T}{|\Delta\overline{{\bf X}}_{2i}|^2} $.

{\mathcal A}_N :=
\dfrac{\sum_{i=1}^N |\Delta \overline{{\bf X}}_{2i}|^2}{N} \cdot
\sum_{i=1}^N \dfrac{\Delta\overline{{\bf X}}_{2i} \Delta\overline{{\bf X}}_{2i}^T}{|\Delta\overline{{\bf X}}_{2i}|^2}
= \dfrac{\sum_{i=1}^N |\Delta \overline{{\bf X}}_{2i}|^2}{p}
\cdot \widetilde{\boldsymbol{\Sigma}},

Instead of the latent process $({\bf X}_t)$, the observed contaminated process $({\bf Y}_t)$ is usually assumed to follow the additive model
\begin{equation}
{\bf Y}_{t} = {\bf X}_{t} + \bm\varepsilon_{t}, \hspace{1cm} \text{for~} t\in [0,1], \end{equation}
where $\bm\varepsilon_{t} = (\varepsilon_{t}^{(1)}, \cdots,\varepsilon_{t}^{(p)})^\mathrm{T}$ denotes the noise process.

The PA-ATVA matrix is then defined as
\begin{equation*}
{\mathcal{\bm B}}_{M}:= 3\frac{\sum_{i=1}^M|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2}{M}\cdot \sum_{i=1}^M\frac{\Delta\widetilde{\overline{\bf{Y}}}_{2i}(\Delta\widetilde{\overline{\bf{Y}}}_{2i})^{\mathrm{T}}}{|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2} =  3\frac{\sum_{i=1}^M|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2}{p}\cdot\widetilde{\bm{\Xi}},
\end{equation*}
where
\begin{equation}
\widetilde{\bm{\Xi}} := \frac{p}{M} \sum_{i=1}^M\frac{\Delta\widetilde{\overline{\bf{Y}}}_{2i}(\Delta\widetilde{\overline{\bf{Y}}}_{2i})^{\mathrm{T}}}{|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2}. \end{equation}

Suppose that Assumptions \eqref{asm:class_c}--\eqref{asm:LSD_bH} and \eqref{asm:error}--\eqref{asm:bdd_L} hold.
Further, assume that $\max\limits_{1\leq i \leq n, 1\leq q\leq  p} nh(s_{T_i}^{(q)} - t_i) \to 0 $, almost surely.
Then, as $p\to\infty$, the ESDs of ICV and ${\mathcal{\bm B}}_M^*$ converge almost surely to probability distributions $H$ and $F^{{\mathcal{\bm B}}^*}$, respectively, where $H$ satisfies \eqref{eq: determine of H} and $F^{{\mathcal{\bm B}}^*}$ is determined by $H$ in that its Stieltjes transform $m_{{\mathcal{\bm B}}^*}(z)$ satisfies the Mar\v{c}enko--Pastur equation,
\begin{equation}
m_{{\mathcal{\bm B}}^*}(z) = \int_{\tau\in \mathbb{R}} \frac{1}{\tau(1 - c(1 + zm_{{\mathcal{\bm B}}^*}(z))) - z}dH(\tau),\hspace{0.2cm}\text{for}~z\in \mathbb{C^{+}}.
\end{equation}

\begin{split}
\mathcal{G} = \bigg[2M_{\tau}^{1/2}, 0.2M_{\tau}, 0.4M_{\tau},
0.6M_{\tau}, 0.8M_{\tau},
 M_{\tau} - 2.5M_{\tau}^{1/2}, M_{\tau} - 1.5M_{\tau}^{1/2}\bigg]
\end{split}

The solution of ${\bf w}$ is
\begin{equation} {\bf w} = \frac{(\textrm{ICV})^{-1}\bm{1}_p}{\bm{1}_p^{{\mathrm{T}}} (\textrm{ICV})^{-1}\bm{1}_p}.
\end{equation}

Under the assumptions of Theorem \ref{thm:LSD_TVA},
the ESD of the ICV matrix converges almost surely in distribution to a probability distribution $H$ as $p\to\infty$ defined by
\begin{equation}
H(x) = \breve{H}(x/\theta), \end{equation}
where $\theta = \int_0^1(\gamma_t^*)^2dt$.
Moreover,
\begin{equation}
\lim\limits_{p\to\infty} \frac{1}{p}\sum_{i = 1}^N |\Delta\overline{\bf{X}}_{2i}|^2 =  \int_0^1 (\dfrac 13 + \dfrac 16 f_{2,s}^*)(\gamma_s^*)^2ds,\hspace{0.5cm} \text{almost surely}. \end{equation}

(Lemma 1 in \cite{ZhengandLi20112}). Suppose that for each $p$, ${\bf v}_l = (v_l^1, \cdots, v_l^p)^\mathrm{T}$ and $\bm w_l = (w_l^1,\cdots,w_l^p)^{\mathrm{T}},l =1, \cdots, m$, are all $p$-dimensional vectors. Define
\[\bm{\widetilde{S}}_m = \sum_{l=1}^m (\bm v_l + \bm w_l)(\bm v_l + \bm w_l)^\mathrm{T} \text{~and~} \bm S_m = \sum_{l=1}^mw_l(w_l)^\mathrm{T}.\]
Suppose the following conditions are satisfied:
\begin{itemize}
  \item $m = m(p)$ with $\lim_{p\to\infty} p/m = c >0$;
  \item there exists a sequence $\epsilon_p = o(1/\sqrt{p})$ such that for all $p$ and all $l$, all the entries of $\bm v_l$ are bounded by $\epsilon_p$ in absolute value;
  \item $\lim\sup_{p\to\infty}\begin{rm}tr\end{rm}(\bm S_m)/p<\infty$ almost surely.
\end{itemize}
Then $L(F^{\bm{\widetilde{S}}_m}, F^{\bm S_m}) \to 0$ almost surely, where for any two probability distribution functions $F$ and $G$, $L(F, G)$ denotes the Levy distance between them.

Then we separate $\Delta\overline{{\bf X}}_{2i}$ into two parts,
\begin{equation}
\Delta\overline{\bf{X}}_{2i} = \sqrt{w_i}(\boldsymbol{\Lambda}{\bf Z}_{i} + {\bf V}_i), \end{equation}
where
\begin{equation}
w_i = \sum_{j=1}^{L_{2i}}a_{2i,j}^2\int_{s_{T_{2i-1} + j -1}}^{s_{T_{2i-1} + j}}\gamma_t^2dt +  \sum_{j=1}^{L_{2i-1}}b_{2i-1,j}^2\int_{ s_{T_{2i-2} + j -1} }^{ s_{T_{2i-2} + j}}\gamma_t^2dt, \end{equation}
\[{\bf Z}_i =  \frac{1}{\sqrt{w_i}}\left[\sum_{j=1}^{L_{2i}}a_{2i,j}\int_{s_{T_{2i-1} + j -1} }^{s_{T_{2i-1} + j} }\gamma_td{\bf W}_t +  \sum_{j=1}^{L_{2i-1}}b_{2i-1,j}\int_{s_{T_{2i-2} + j -1} }^{s_{T_{2i-2} + j} }\gamma_td{\bf W}_t \right],\]
and
\[{\bf V}_i =  \frac{1}{\sqrt{w_i}}\left[\sum_{j=1}^{L_{2i}}a_{2i,j}\int_{s_{T_{2i-1} + j -1} }^{s_{T_{2i-1} + j} }\boldsymbol{\mu}_tdt +  \sum_{j=1}^{L_{2i-1}}b_{2i-1,j}\int_{s_{T_{2i-2} + j -1} }^{s_{T_{2i-2} + j} }\boldsymbol{\mu}_tdt  \right].\]

By a similar argument to that used in (3.34) in \cite{ZhengandLi20112}, we have
\begin{equation}
\max\limits_{1\leq i \leq N} \big|\frac{1}{p}|\boldsymbol{\Lambda}{\bf Z}_i|^2-1\big| \to 0, \hspace{0.5cm} \text{almost surely}. \end{equation}

By the boundedness of the $|{\bf V}_i|$, we further have
\begin{equation}
\max\limits_{1\leq i \leq N} \big|\frac{1}{p}|{\bf V}_i + \boldsymbol{\Lambda}{\bf Z}_i|^2-1\big| \to 0, \hspace{0.5cm} \text{almost surely}. \end{equation}

Then
\begin{equation*}
\begin{split}
&\sum_{i=1}^N\int_{(2i-2)/n}^{2i/n}|N E(w_i) - w_s|ds\\
=&\sum\limits_{\ell_j \in \{\ell_1,\cdots,\ell_J\}}\int_{\frac{2\ell_j-2}{n}}^{\frac{2\ell_j}{n}}|N E(w_{\ell_j}) - w_s|ds +
\sum\limits_{i \notin \{\ell_1,\cdots,\ell_J\}}\int_{\frac{2i-2}{n}}^{\frac{2i}{n}}|N E(w_i) - w_s|ds\\
:= &D_1 + D_2.\\
\end{split}
\end{equation*}

For all large $n$, because $|\gamma_t|\leq C$ and $1\leq L_i< L^*$, for any $i, t$, we have
\[
\begin{split}
&|D_2| \\
\leq& \sum\limits_{i}\int_{\frac{2i-2}{n}}^{\frac{2i}{n}}N|E(w_i) - E(w_i^*)|ds + \sum\limits_{i\notin \{\ell_1,\cdots,\ell_J\}}\int_{\frac{2i-2}{n}}^{\frac{2i}{n}}N| E(w_i^*) - E(\widetilde{w}_i^*)|ds \\
+&\sum\limits_{i}\int_{\frac{2i-2}{n}}^{\frac{2i}{n}}| NE(\widetilde{w}_i^*) - N\widetilde{\widetilde{w}}_i^*|ds  +\sum\limits_{i\notin \{\ell_1,\cdots,\ell_J\}}\int_{\frac{2i-2}{n}}^{\frac{2i}{n}}| N\widetilde{\widetilde{w}}_i^* - w_s|ds\\
\to& 0, ~~~\text{almost surely.}
\end{split}
\]
This completes the proof of \eqref{eq: convergence of Vi plus lambda Zi}.\hspace{\fill}$\blacksquare$ \hbox{} \medskip

Following the same arguments as in the proof of Proposition C.1 of \cite{XiaandZheng20182}, it suffices to show that
\begin{equation}
\max\limits_{1\leq i \leq M, 1\leq j \leq p} \frac{\sqrt{p}|\Delta\widetilde{\overline{\bm{\varepsilon}}}_{2i}^{(j)}|}{|\Delta\widetilde{\overline{\bf{X}}}_{2i}|}\to 0,\hspace{1cm} \text{almost surely}. \end{equation}

From the fact that  $a_{i,j} + b_{i,j} = 1$, we can further write $ \Delta\widetilde{\overline{\bf{X}}}_{2i}$ as

\begin{align} \Delta\widetilde{\overline{\bf{X}}}_{2i} = & \frac{1}{h}\sum_{j=1}^{L_{2ih}}a_{2ih,j}\Delta_{2ih,j}{\bf X} \notag\\
&+ \sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left(1-\frac{|h-l+1|}{h}\right)\Delta_{(2i-2)h+l,j}{\bf X} \notag\\
&+ \sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[ \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right]\Delta_{(2i-2)h+l,j}{\bf X} \notag\\
:= & \widetilde{\bf{V}}_i + \sqrt{\psi_i}\boldsymbol{\Lambda}\widetilde{\bf{Z}}_i,
\end{align}
where
\begin{align*}
\psi_i &:= \frac{1}{h^2}\sum_{j=1}^{L_{2ih}}a_{2ih,j}^2\int_{s_{T_{2ih-1} + j - 1}}^{s_{T_{2ih-1} + j}}\gamma_t^2dt\\
&+\sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[\left(1-\frac{|h-l+1|}{h}\right) + \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right]^2\\
&\hspace{2cm}\cdot\int_{s_{T_{(2i-2)h+l-1} + j - 1}}^{s_{T_{(2i-2)h+l-1} + j}} \gamma_t^2dt,
\end{align*}
\begin{align*}
\widetilde{\bf{Z}}_i& := \frac{1}{\sqrt{\psi_i}}\frac{1}{h}\sum_{j=1}^{L_{2ih}}a_{2ih,j}\int_{s_{T_{2ih-1} + j - 1}}^{s_{T_{2ih-1} + j}}\gamma_td{\bf W}_t\notag\\
&+\sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[\left(1-\frac{|h-l+1|}{h}\right) + \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right] \\
&\hspace{2cm}\cdot\int_{s_{T_{(2i-2)h+l-1} + j - 1}}^{s_{T_{(2i-2)h+l-1} + j}} \gamma_td{\bf W}_t,
\end{align*}
and
\begin{align*}
\widetilde{\bf{V}}_i &:= \frac{1}{h}\sum_{j=1}^{L_{2ih}}a_{2ih,j}\int_{s_{T_{2ih-1} + j - 1}}^{s_{T_{2ih-1} + j}}\boldsymbol{\mu}_tdt\notag\\
&+\sum_{l=1}^{2h-1}\sum_{j=1}^{L_{(2i-2)h + l}} \left[\left(1-\frac{|h-l+1|}{h}\right) + \frac{|h-l+1| - |h-l|}{h} b_{(2i-2)h+l,j}\right] \\
&\hspace{2cm}\cdot\int_{s_{T_{(2i-2)h+l-1} + j - 1}}^{s_{T_{(2i-2)h+l-1} + j}}\boldsymbol{\mu}_tdt.
\end{align*}

Otherwise, by using a similar trick as in the proof of (3.34) of \cite{ZhengandLi20112}, we have
\begin{equation} \max\limits_{1\leq i \leq M} |\frac{1}{p}|\boldsymbol{\Lambda}\widetilde{\bf{Z}}_i|^2  - 1 | \to 0, ~~~\text{almost surely}.
\end{equation}

Combining this with the fact that all the entries of $\widetilde{\bf{V}}_i$ are of order $O(h/n) = o(1/\sqrt{p})$, we have
\begin{equation}
\frac{\sum_{i=1}^M|\Delta\widetilde{\overline{\bf{X}}}_{2i}|^2}{p} = \frac{\sum_{i=1}^M|\widetilde{\bf{V}}_i + \sqrt{\psi_i}\boldsymbol{\Lambda}\widetilde{\bf{Z}}_i|^2}{p} = \sum_{i=1}^M\psi_i + o_{a.s.}(1). \end{equation}

It remains to prove that
\begin{equation} \lim_{p\to\infty} 3\frac{\sum_{i=1}^M|\Delta\widetilde{\overline{\bf{X}}}_{2i}|^2}{p} = \theta, \hspace{1cm} \text{almost surely},
\end{equation}
and
\begin{equation} \frac{\sum_{i=1}^M\Delta\widetilde{\overline{\bf{X}}}_{2i}^{\mathrm{T}}\Delta\widetilde{\overline{\bm{\varepsilon}}}_{2i}}{p}\to 0, \hspace{1cm}\text{almost surely}.
\end{equation}

Similar to the proof of Lemma \ref{lem:LSD ttSigma}, we first show that
there exists a constant $C>0$ such that for large $M$
\begin{equation} \min\limits_{1\leq i\leq M} |\Delta \widetilde{\overline{\bf{X}}}^*_{2i}|^2 \geq C,
\end{equation}
and
\begin{equation} \max\limits_{1\leq i \leq M, 1\leq j \leq p} \sqrt{p}|\Delta (\widetilde{\overline{\bm{\varepsilon}}}_{2i}^{*})^{(j)} | \to 0, ~~~\text{almost surely,}
\end{equation}
which leads to the result that the PA-ATVA matrix based on noisy observations $\Delta\widetilde{\overline{\bf{Y}}}^*_{2i}$ and that based on latent log price $\Delta\widetilde{\overline{\bf{X}}}^*_{2i}$ have the same LSD.

Thus, \eqref{eq: xy same require in AT} follows if we can show that there exists a constant $C>0$ such that for large $M$
\begin{equation} \min\limits_{1\leq i \leq M}|{\bf W}_{i}|^2\geq C,
\end{equation}
and
\begin{equation} \max\limits_{1\leq i \leq M, 1\leq q \leq p}\sqrt{p}|R_{i1}^{(q)} + R_{i2}^{(q)} +  R_{i3}^{(q)}|\to 0,~~~\text{almost surely.}
\end{equation}

Then the averaged nonlinear shrinkage (ANS) estimator of ICV is defined as
\begin{equation*}
\widehat{\boldsymbol{\Sigma}}_{\textrm{ANS}}:= \hat{\theta}_p\cdot\frac{1}{B} \sum_{k=1}^B \widetilde{\bm{\Xi}}^{(k)}_{\textrm{ANS}}, ~~\widetilde{\bm{\Xi}}^{(k)}_{\textrm{ANS}} = \widetilde{\bf U}_1^{(k)} \textrm{diag}((\widetilde{\bf U}_1^{(k)})^{{\mathrm{T}}} \widetilde{\boldsymbol{\Xi}}_2^{(k)}\widetilde{\bf U}_1^{(k)}) (\widetilde{\bf U}_1^{(k)})^{{\mathrm{T}}},
\end{equation*}
where $\textrm{diag}({\bf A})$ sets all non-diagonal elements of matrix ${\bf A}$ to zero.

To this end, $M_{\tau_1}$ is chosen using the following criterion,
\begin{equation}\arg\min\limits_{M_{\tau_1}\in \mathcal{G}} \bigg| \bigg|  \frac{1}{B} \sum_{k = 1}^B (\widetilde{\bm{\Xi}}^{(k)}_{\textrm{ANS}} -  \widetilde{\bm{\Xi}}_2^{(k)}) \bigg| \bigg|_F^2, \end{equation}
where
\begin{equation}
\begin{split}
\mathcal{G} = \bigg[2M_{\tau}^{1/2}, 0.2M_{\tau}, 0.4M_{\tau},
0.6M_{\tau}, 0.8M_{\tau},
 M_{\tau} - 2.5M_{\tau}^{1/2}, M_{\tau} - 1.5M_{\tau}^{1/2}\bigg]
\end{split} \end{equation}
is the candidate set for $M_{\tau_1}$, recommended by \cite{Lam2016} and \cite{Lametal2017}.
